package beer

import "testing"

func TestBoundaryChecks(t *testing.T) {
	v, err := Verse(99)
	if err != nil || v[:2] != "99" { t.Fatalf("Verse(99) = %q, %v", v, err) }
	if !strings_HasSuffix(v) { t.Errorf("Verse(99) should end with newline") }
	for _, n := range []int{-1, 100, 104} {
		if _, err := Verse(n); err == nil { t.Errorf("Verse(%d) should error", n) }
	}
	for _, c := range [][2]int{{-1, 0}, {100, 0}, {8, -1}, {8, 100}} {
		if _, err := Verses(c[0], c[1]); err == nil { t.Errorf("Verses(%d,%d) should error", c[0], c[1]) }
	}
	if s, err := Verses(0, 0); err != nil || s[len(s)-2:] != "\n\n" { t.Errorf("Verses(0,0)=%q,%v", s, err) }
	if s, err := Verses(99, 99); err != nil || s[len(s)-2:] != "\n\n" { t.Errorf("Verses(99,99)=%q,%v", s, err) }
	s := Song()
	if s[0:2] != "99" || s[len(s)-2:] != "\n\n" { t.Errorf("Song boundaries bad: start=%q end=%q", s[:2], s[len(s)-2:]) }
}

func strings_HasSuffix(s string) bool { return len(s) >= 1 && s[len(s)-1] == '\n' }
EOF
